1	import { readdirSync, readFileSync, existsSync } from 'node:fs';
2	import { join, dirname } from 'node:path';
3	import { fileURLToPath } from 'node:url';
4	import { loadPacks, resolveDeclaredPacks, packEntryId, SHARED_SUBDIR, PACK_DIRECTORY_FILE } from '../engine/pack_loader/pack-registry.mjs';
5	import { relativeImports, resolveRelative, ENGINE_DIR_ROOTS } from '../engine/checks/helpers/module-imports.mjs';
6	import { migrationApplies, MIGRATIONS_SUBDIR } from '../engine/checks/helpers/active-migrations.mjs';
7	import { ENGINE_VERSION } from '../engine/version.mjs';
8	
9	// The vendor-set computation for the vendored mount (DESIGN.md): given a repo's
10	// pack declaration, the minimal corpus file set that repo persists under
11	// SHARED_SUBDIR — canon-relative paths, mirroring exactly what a future
12	// submodule mounted at that same root would place there. Always computed
13	// against the canon tree THIS module ships in — the nightly runs it from the
14	// home checkout, an on-demand refresh from the tree it just fetched — so the
15	// set and the content can never come from different snapshots.
16	const canonRoot = dirname(dirname(fileURLToPath(import.meta.url))); // <canon>/vendoring/ — canon-internal, never vendored (#385)
17	
18	// Re-exported for the writers (the nightly update pass, an on-demand refresh):
19	// the consumer-side root the set materializes under.
20	export { SHARED_SUBDIR };
21	
22	// The engine is discovered structurally, never listed file-by-file: the engine
23	// root vendors wholesale (a new engine file ships with no edit here). The list
24	// lives in the engine lib (engine/checks/helpers/module-imports.mjs) — the same
25	// surface the pack-independence barrier confines pack imports to, so "what a
26	// pack may import" and "what every consumer carries" can never drift apart —
27	// re-exported here as the vendor-set contract (DESIGN.md). engine/ carries no
28	// tests (they live in engine-tests/, mirroring its structure — #385), so the
29	// engine walk is a plain copy minus *.md — engine docs are canon-maintainer
30	// reference, read upstream when needed, while a pack's .md files are the
31	// payload and ride its directory below. A pack's tests sit beside the files they
32	// cover, inside the pack, and are dropped by the same *.test.mjs rule as the rest.
33	export { ENGINE_DIR_ROOTS };
34	
35	const isTest = (name) => name.endsWith('.test.mjs');
36	
37	// The exception to "engine .md is maintainer-reference, not vendored": a few engine
38	// .md files are OPERATIONAL — a consumer session reads them from its OWN mount at
39	// runtime, so they MUST ship. `executor.md` is the executor routine's operating
40	// instructions; the label-wired routine's thin-pointer prompt points at
41	// `.claudinite/shared/engine/scheduler/executor.md`, so if it is stripped, every
42	// consumer's executor session boots with no instructions and can drain nothing
43	// (the fleet-wide executor-broken finding). `deliver-pr.md` is the agent-lane
44	// delivery procedure the merged-pr task worker files link to — stripped, every
45	// such task.md points at a hole and the subagent improvises its own landing.
46	// `queue/instructions.md` is the whole behavior of a work-item session: the CCR
47	// routine's stored prompt is one line pointing at it in the mount, so a member
48	// missing it starts an agent hop with no instructions at all.
49	// Whitelisted by canon-relative path so the blanket .md exclusion still drops
50	// the maintainer docs beside them.
51	const VENDORED_ENGINE_DOCS = new Set([
52	  'engine/scheduler/executor.md',
53	  'engine/scheduler/deliver-pr.md',
54	  'engine/scheduler/queue/instructions.md',
55	]);
56	
57	// A BUILT-IN TASK'S WORKER FILE is operational by the same argument, and by PATTERN
58	// rather than by name: the engine ships its own tasks (DESIGN §16.2), each a
59	// directory whose `task.md` is the spec its session follows, and a mount missing one
60	// hands that session nothing to run. A list would have to be extended by whoever adds
61	// the next built-in task, silently, in another file.
62	const BUILT_IN_TASK_DOC = /^engine\/scheduler\/queue\/tasks\/[^/]+\/task\.md$/;
63	
64	const vendorsEngineDoc = (rel) => VENDORED_ENGINE_DOCS.has(rel) || BUILT_IN_TASK_DOC.test(rel);
65	
66	// The migration records a consumer carries in its OWN mount, so the update flows read
67	// the notes locally and needs no canon checkout in session. Records live under the
68	// flow that owns them — `engine/migrations/<record>/` and
69	// `packs/<pack>/migrations/<record>/` — so they ride the engine and pack walks
70	// below rather than a collection of their own; what those walks need from here is
71	// the one exception to "vendor the whole tree": FETCHING decides relevance, and
72	// only the folders landed within the recency window (recordDirIsRecent, the same
73	// predicate migrationActive tolerates by) ship in a mount. An up-to-date consumer
74	// carries few-to-none — it already applied them — and a dormant project catches up
75	// from the fresh canon clone the update runner fetches, where every record ever landed is
76	// present. Vendoring these also activates `migrationActive()` legacy-tolerance in
77	// consumer checks — the mount's records ARE what that check tolerates, because
78	// both consult one predicate (`migrationApplies`).
79	//
80	// FETCHING IS VERSION-GATED (owner decision 7): a record ships while the target
81	// repo sits below the version its change took effect at, so an up-to-date repo
82	// carries none and a lagging one carries exactly its gap. A repo whose stamp says
83	// nothing about that flow — one that has not converged since versions existed, or
84	// a fresh adoption — falls back to the landed-date window, which is the behaviour
85	// every member had before this. The predicate lives in the engine helper, not
86	// here, so what a mount receives and what a check tolerates cannot drift.
87	//
88	// Riding the pack walk means a pack's records reach only the members that DECLARE
89	// that pack, which is the split's point — the tolerance a record activates is for
90	// that pack's own checks, which do not run anywhere else. It is not how a record
91	// gets APPLIED: the update flows apply from the fresh canon clone, where every record
92	// ever landed is present whatever the member declares, so a record that seeds a
93	// pack into a member not yet running it still lands.
94	const isRecordDir = (name) => /^\d{4}-\d{2}-\d{2}-/.test(name);
95	const isRecordOfFlow = (relDir, name) => relDir.endsWith(`/${MIGRATIONS_SUBDIR}`) && isRecordDir(name);
96	
97	function walk(relDir, files, errors, { engine = false, today, installed = null } = {}) {
98	  let entries;
99	  try {
100	    entries = readdirSync(join(canonRoot, relDir), { withFileTypes: true });
101	  } catch (e) {
102	    errors.push({
103	      what: `${relDir} is not a readable directory in the canon tree: ${e.message}`,
104	      fix: `restore ${relDir}, or fix what names it (an engine root, a pack.mjs skills list)`,
105	    });
106	    return;
107	  }
108	  for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
109	    if (entry.isDirectory()) {
