node -e "
import('./engine/checks/helpers/repo-context.mjs').then(async ({buildContext}) => {
  const { default: rule } = await import('./.claudinite/local/packs/canon-curation/pack-version-bumped.mjs');
  const { runRule } = await import('./engine/checks/helpers/work.mjs');
  const ctx = buildContext({ root: process.cwd(), mode: 'changed' });
  const findings = runRule(rule, ctx);
  console.log(JSON.stringify(findings, null, 2));
});
"

